class Wallet {
    private int amount = 9;
    void add(int value) { if (value > 0) amount += value; }
    void spend(int value) { if (value > 0 && value <= amount) amount -= value; }
    int getAmount() { return amount; }
}
public class Main {
    public static void main(String[] args) {
        Wallet wallet = new Wallet();
        wallet.add(3); wallet.spend(4);
        System.out.println(wallet.getAmount());
    }
}
